WITH car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,sigla_uf,area FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2,3),b AS (SELECT op.ano_emissao,c.id_imovel,c.id_municipio,c.sigla_uf,c.area,op.id_referencia_bacen,op.valor_parcela_credito/n.n_imoveis credito,op.area_financiada/n.n_imoveis area_financiada FROM p JOIN n USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao BETWEEN 2013 AND 2026),mun AS (SELECT id_municipio,sigla_uf,COUNT(DISTINCT IF(area<0.1,id_imovel,NULL)) micro_imoveis,SUM(IF(area<0.1,credito,0)) credito_micro,SUM(credito) credito_total FROM b GROUP BY 1,2) SELECT mun.id_municipio,d.nome,mun.sigla_uf,micro_imoveis,credito_micro,credito_total,SAFE_DIVIDE(credito_micro,credito_total) participacao_micro FROM mun LEFT JOIN `basedosdados.br_bd_diretorios_brasil.municipio` d USING(id_municipio) WHERE credito_micro>=10000000 ORDER BY participacao_micro DESC LIMIT 30